cd /workspace && python3 - <<'EOF'
import sys,random
sys.path.insert(0,'/workspace/project')
from modules.byte_program import *
random.seed(7)
def build(depth=0):
    r=random.random()
    if depth>3 or r<0.35:
        return literal(bytes(random.randrange(256) for _ in range(random.randrange(0,20))))
    if r<0.6:
        return concat(build(depth+1),build(depth+1))
    if r<0.8:
        return repeat(build(depth+1),random.randrange(0,5))
    node=build(depth+1)
    lo=random.randrange(0,node.length+1); hi=random.randrange(lo,node.length+1)
    return cut(node,lo,hi)
def flat(node):
    return materialize(node, 10**9)
ok=True
for trial in range(400):
    n=build()
    raw=flat(n)
    if n.length!=len(raw) or n.hash!=hash_bytes(raw): print('MISMATCH whole',n.length,len(raw)); ok=False;break
    for _ in range(10):
        if not raw: continue
        lo=random.randrange(0,len(raw)); hi=random.randrange(lo,len(raw)+1)
        ln,h=hash_range(n,lo,hi)
        if ln!=hi-lo or h!=hash_bytes(raw[lo:hi]):
            print('MISMATCH range',lo,hi,ln,h,hash_bytes(raw[lo:hi])); ok=False; break
        w=window(n,lo,hi)
        if w!=raw[lo:hi]: print('MISMATCH window',lo,hi); ok=False;break
        for p in range(lo,hi):
            if byte_at(n,p)!=raw[p]: print('MISMATCH byte',p); ok=False;break
    if not ok: break
print('all ok' if ok else 'FAILED')
# check the earlier Rep hash_range question
n=cut(Rep(literal(b'ab'),100),3,97)
print(n.length, hex(n.hash), hex(hash_bytes((b'ab'*100)[3:97])))
EOF
